import heapq

def find_min_spanning_tree(edges):
    # Create a disjoint set data structure to keep track of connected components
    uf = UnionFind()

    # Initialize the priority queue with edges in increasing order of weight
    pq = [(weight, vertex1, vertex2) for vertex1, vertex2, weight in edges]
    heapq.heapify(pq)

    # Process edges in the priority queue
    mst = []
    while pq:
        weight, vertex1, vertex2 = heapq.heappop(pq)

        # Check if the vertices are in the same connected component
        if uf.connected(vertex1, vertex2):
            continue

        # Union the connected components and add the edge to the MST
        uf.union(vertex1, vertex2)
        mst.append((vertex1, vertex2, weight))

    return mst

class UnionFind:
    def __init__(self):
        self.parent = {}
        self.rank = {}

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def connected(self, x, y):
        return self.find(x) == self.find(y)

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)

        if root_x == root_y:
            return

        if self.rank[root_x] > self.rank[root_y]:
            self.parent[root_y] = root_x
        elif self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
        else:
            self.parent[root_y] = root_x
            self.rank[root_x] += 1

